with inserted as (insert into public.runtime_token_usage(call_id,job_id,node_id,worker_id,call_index,model,completion_tokens,prompt_tokens,source) values($1::text::uuid,$2,$3,$4,$5,(select model from public.jobs where job_id=$2),$6,$7,'runtime') on conflict do nothing returning completion_tokens,prompt_tokens) update public.runtime_token_totals set completion_tokens=runtime_token_totals.completion_tokens+inserted.completion_tokens,prompt_tokens=runtime_token_totals.prompt_tokens+coalesce(inserted.prompt_tokens,0),measured_calls=measured_calls+1,last_recorded_at=now() from inserted where id=1;
